def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    arities = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    for index, operation in enumerate(ops):
        tokens = operation.split(" ")
        verb = tokens[0]

        if len(tokens) != arities.get(verb, 0) or any(
            token == "" for token in tokens
        ):
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue

            for account, old_balance, was_frozen in history.pop():
                if old_balance is None:
                    del balances[account]
                else:
                    balances[account] = old_balance

                if was_frozen:
                    frozen.add(account)
                else:
                    frozen.discard(account)
            continue

        account = tokens[1]
        amount = 0

        if verb in ("open", "deposit", "withdraw", "transfer"):
            digits = tokens[-1]
            if not digits.isascii() or not digits.isdigit():
                rejected.append(index)
                continue

            # Small chunks also support amounts beyond Python's int-string limit.
            digits = digits.lstrip("0")
            for start in range(0, len(digits), 18):
                chunk = digits[start:start + 18]
                amount = amount * (10 ** len(chunk)) + int(chunk)

        if verb == "open":
            valid = account not in balances
        elif verb == "deposit":
            valid = account in balances and amount > 0
        elif verb == "withdraw":
            valid = (
                account in balances
                and account not in frozen
                and amount > 0
                and balances[account] >= amount
            )
        elif verb == "transfer":
            destination = tokens[2]
            valid = (
                account != destination
                and account in balances
                and destination in balances
                and account not in frozen
                and amount > 0
                and balances[account] >= amount
            )
        elif verb == "freeze":
            valid = account in balances and account not in frozen
        else:  # unfreeze
            valid = account in balances and account in frozen

        if not valid:
            rejected.append(index)
            continue

        affected = (account, tokens[2]) if verb == "transfer" else (account,)
        history.append(tuple(
            (name, balances.get(name), name in frozen)
            for name in affected
        ))

        if verb == "open":
            balances[account] = amount
        elif verb == "deposit":
            balances[account] += amount
        elif verb == "withdraw":
            balances[account] -= amount
        elif verb == "transfer":
            balances[account] -= amount
            balances[tokens[2]] += amount
        elif verb == "freeze":
            frozen.add(account)
        else:
            frozen.remove(account)

    return balances, rejected
